import {mountExperiences} from './experiences.js';
import {LESSON,COURSES,activateLesson,storageKey} from './lesson.js';
import {coursePage as getCoursePage} from './catalog.js';
import {ROLE_IDS,clamp,position,puck,sample,getPhase,pathBetween,comparePrediction,readProgress} from './engine.js';
const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';
let progress,storageWorks=true;try{progress=readProgress(localStorage.getItem(storageKey()));}catch{storageWorks=false;progress=readProgress(null);}
const state={t:0,role:'C',playing:false,speed:1,zoom:matchMedia('(max-width:750px)').matches,trails:true,opponents:true,support:false,future:false,mode:'watch',guess:null,revealed:false};
let experiences=null;
let categoryFilter='全部',courseQuery='',coursePage=0,randomBag=[];
const COURSE_PAGE_SIZE=6;
let frameId=null,lastFrame=null,toastTimer=null,lastPhase=-1,keyCursor={x:500,y:300};
const playerNodes=new Map(),opponentNodes=new Map();
function el(tag,attrs={},text){const n=document.createElementNS(NS,tag);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,String(v));if(text!==undefined)n.textContent=text;return n;}
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3000);}
function savedProgress(lesson){try{return readProgress(localStorage.getItem(storageKey(lesson)));}catch{return readProgress(null);}}
const scenarios=COURSES.flatMap(course=>course.cases.map(scenario=>({course,scenario})));
function updateBankProgress(){const attempted=scenarios.filter(x=>Object.keys(x.scenario.lesson===LESSON?progress.predictions:savedProgress(x.scenario.lesson).predictions).length>0).length;$('bankProgress').textContent=`${attempted} / ${scenarios.length} 個情境已做過預判`; }
function persist(){try{localStorage.setItem(storageKey(),JSON.stringify({lessonId:LESSON.id,caseId:LESSON.caseId,version:1,...progress}));storageWorks=true;}catch{storageWorks=false;}$('saveStatus').textContent=storageWorks?'學習紀錄保存在此瀏覽器':'此瀏覽器無法保存；請匯出紀錄備份';updateBankProgress();}
function makeTokens(){for(const role of ROLE_IDS){const n=el('g',{'data-role':role,tabindex:'0',role:'button','aria-label':`切換至${LESSON.roles[role].name}`,class:'player-token'});const halo=el('circle',{r:27,fill:'none',stroke:'#de725d','stroke-width':2.5,opacity:0}),body=el('circle',{r:18,fill:'#277b76',stroke:'#fff','stroke-width':2}),text=el('text',{class:'token-label'},role);n.append(halo,body,text);$('players').append(n);playerNodes.set(role,{n,halo,body});}for(const id of Object.keys(LESSON.opponents)){const n=el('g',{'aria-hidden':'true'});n.append(el('circle',{r:16,fill:'#667774',stroke:'#fff','stroke-width':2,opacity:.75}),el('text',{class:'token-label',style:'font-size:10px;opacity:.8'},id==='OC'?'C':id.startsWith('OD')?'D':'W'));$('opponents').append(n);opponentNodes.set(id,n);}}
function setRole(role){if(!ROLE_IDS.includes(role))return;pause();state.role=role;state.guess=null;state.revealed=false;state.mode='watch';state.future=false;$('futureToggle').setAttribute('aria-pressed','false');$('futureToggle').textContent='顯示下一段路線';$('roleNote').value=progress.notes[role]||'';lastPhase=-1;render();}
function updateProgress(){const count=progress.viewed.length;$('viewedCount').replaceChildren(document.createTextNode(String(count)),Object.assign(document.createElement('span'),{textContent:' / 5'}));$('viewedBar').style.width=(count/5*100)+'%';for(const button of document.querySelectorAll('.role-switch [data-role]')){const role=button.dataset.role;button.classList.toggle('active',role===state.role);button.classList.toggle('viewed',progress.viewed.includes(role));button.setAttribute('aria-pressed',String(role===state.role));}const marked=progress.viewed.includes(state.role);$('markViewed').classList.toggle('marked',marked);$('markViewed').textContent=marked?'✓ 已看過（再按可取消）':'✓ 這個位置看過了';}
function renderBoard(){const t=state.t;$('rink').setAttribute('viewBox',state.zoom?(LESSON.number!=='01'?`${clamp(position(state.role,t).x-200,40,530)} ${clamp(position(state.role,t).y-225,50,100)} 430 450`:'300 75 430 450'):'0 0 1000 600');$('rinkWrap').classList.toggle('zoom',state.zoom);$('fullView').setAttribute('aria-pressed',String(!state.zoom));$('neutralView').setAttribute('aria-pressed',String(state.zoom));for(const [role,{n,halo,body}] of playerNodes){const p=position(role,t),focus=role===state.role;n.setAttribute('transform',`translate(${p.x} ${p.y})`);body.setAttribute('fill',focus?'#de725d':'#277b76');halo.setAttribute('opacity',focus?'1':'0');n.setAttribute('aria-pressed',String(focus));n.setAttribute('aria-label',`${LESSON.roles[role].name}，${LESSON.roles[role].job}`);}for(const [id,n] of opponentNodes){const p=sample(LESSON.opponents[id],t);n.setAttribute('transform',`translate(${p.x} ${p.y})`);n.style.display=state.opponents?'':'none';}
 const trail=$('trails');trail.replaceChildren();if(state.trails)for(const role of ROLE_IDS)trail.append(el('polyline',{points:pathBetween(role,Math.max(0,t-3),t),fill:'none',stroke:role===state.role?'#de725d':'#5f9c90','stroke-width':role===state.role?3:1.5,opacity:role===state.role?.85:.22,'stroke-linecap':'round','stroke-linejoin':'round'}));
 $('connections').replaceChildren();if(state.support&&t>=3&&state.mode!=='predict'){const [c,ld,rd]=(LESSON.supportRoles||['C','LD','RD']).map(r=>position(r,t));$('connections').append(el('path',{d:`M${c.x} ${c.y} L${ld.x} ${ld.y} L${rd.x} ${rd.y}`,fill:'none',stroke:'#78b1a3','stroke-dasharray':'7 7','stroke-width':2,opacity:.7}));}
 $('future').replaceChildren();if(state.future&&state.mode!=='predict'){const end=state.revealed?LESSON.predictionTime:Math.min(LESSON.duration,t+2.4),start=state.revealed?LESSON.checkpoint:t;if(end>start)$('future').append(el('polyline',{points:pathBetween(state.role,start,end),fill:'none',stroke:'#277b76','stroke-width':3,'stroke-dasharray':'7 7',opacity:.7}));}
 const p=puck(t);$('puck').replaceChildren(el('ellipse',{cx:p.x+5,cy:p.y+8,rx:10,ry:3,fill:'#1233',opacity:.4}),el('circle',{cx:p.x+7,cy:p.y+5,r:6,fill:'#163334',stroke:'#fff','stroke-width':1.5}));
 const prediction=$('prediction');prediction.replaceChildren();if(state.guess){const p=state.guess;prediction.append(el('circle',{cx:p.x,cy:p.y,r:12,fill:'none',stroke:'#c88b36','stroke-width':2.5,'stroke-dasharray':'4 3'}),el('text',{x:p.x+16,y:p.y-12,class:'key-point'},'你的選點'));}if(state.revealed){const p=position(state.role,LESSON.predictionTime);prediction.append(el('circle',{cx:p.x,cy:p.y,r:55,fill:'#277b7610',stroke:'#277b76','stroke-width':2,'stroke-dasharray':'5 5'}),el('text',{x:p.x-38,y:p.y+75,fill:'#277b76','font-size':13},'本課示範區域'));}
 $('practiceBanner').hidden=state.mode!=='predict';document.querySelector('.board-panel').classList.toggle('predicting',state.mode==='predict');}
function renderCopy(){const role=LESSON.roles[state.role],phase=getPhase(state.t),index=LESSON.phases.indexOf(phase);$('focusLabel').textContent=state.role+' '+role.name;$('rolePill').textContent=state.role;$('roleName').textContent=role.name;$('roleJob').textContent=role.job;$('watchText').textContent=role.watch;$('whyText').textContent=role.why;$('riskText').textContent=role.risk;$('phaseLabel').textContent=String(index+1).padStart(2,'0')+' · '+phase.title;$('taskTitle').textContent=phase.title;$('taskBody').textContent=role.tasks[index];$('phaseCue').textContent=phase.cue;$('timeline').value=String(state.t);$('timeValue').textContent=state.t.toFixed(1);$('playText').textContent=state.playing?'暫停':'播放示範';$('playIcon').textContent=state.playing?'Ⅱ':'▶';$('play').setAttribute('aria-label',state.playing?'暫停動畫':'播放示範');$('noteLabel').textContent=state.role+' '+role.name+'的觀察';$('roleExplanation').hidden=state.mode==='predict'&&!state.revealed;$('futureToggle').setAttribute('aria-pressed',String(state.future));$('futureToggle').textContent=state.future?'隱藏下一段路線':'顯示下一段路線';if(state.mode==='predict'){$('taskTitle').textContent='先看局面，做一次預判';$('taskBody').textContent=role.practiceIntro||LESSON.practiceIntro;$('phaseCue').textContent='先選位置，再看示範與理由。';}
 const show=state.mode==='predict'||state.revealed;$('predictionResult').hidden=!show;if(show){$('reveal').disabled=!state.guess;$('reveal').hidden=state.revealed;if(state.revealed){const result=comparePrediction(state.role,state.guess);$('predictionHeading').textContent=result.near?'你的選點接近本課示範區域':'比較你的選點與示範區域';$('predictionBody').textContent=role.why+' 這是示範路線的比較，不是戰術評分；換一種防守，選擇也會不同。';}else{$('predictionHeading').textContent=state.guess?'已記下你的選點':'你會移動到哪裡？';$('predictionBody').textContent=role.prediction+(state.guess?' 按下方按鈕看示範與理由。':' 點冰場選位置；鍵盤可用方向鍵移動游標、Enter 確認。');}}if(index!==lastPhase){lastPhase=index;}}
function render(){renderBoard();renderCopy();updateProgress();experiences?.sync();}
function pause(){state.playing=false;if(frameId!==null)cancelAnimationFrame(frameId);frameId=null;lastFrame=null;if($('playText')){$('playText').textContent='播放示範';$('playIcon').textContent='▶';}}
function tick(now){if(!state.playing)return;if(lastFrame===null)lastFrame=now;const dt=Math.min((now-lastFrame)/1000,.15);lastFrame=now;state.t=clamp(state.t+dt*state.speed,0,LESSON.duration);if(state.t>=LESSON.duration){pause();toast('示範結束。換一個位置，再看他的工作。');}render();if(state.playing)frameId=requestAnimationFrame(tick);}
function play(){if(state.mode==='predict'){toast('先選位置，再按「看示範與解釋」。');return;}if(state.t>=LESSON.duration)state.t=0;state.revealed=false;state.playing=true;lastFrame=null;renderCopy();frameId=requestAnimationFrame(tick);}
function setTime(t){pause();state.t=clamp(t,0,LESSON.duration);state.mode='watch';state.revealed=false;state.guess=null;state.future=false;render();}
function beginPractice(){pause();state.t=LESSON.checkpoint;state.mode='predict';state.guess=null;state.revealed=false;state.future=false;keyCursor=position(state.role,LESSON.checkpoint);$('futureToggle').setAttribute('aria-pressed','false');$('futureToggle').textContent='顯示下一段路線';render();$('rink').focus({preventScroll:true});if(matchMedia('(max-width:750px)').matches)$('rinkWrap').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});}
function setGuess(x,y){if(state.mode!=='predict')return;state.guess={x:clamp(x,40,960),y:clamp(y,50,550)};keyCursor={...state.guess};render();}
function exportProgress(){const records=COURSES.flatMap(c=>c.cases.map(x=>{let saved;try{saved=readProgress(localStorage.getItem(storageKey(x.lesson)));}catch{saved=readProgress(null);}return {lessonId:c.id,caseId:x.id,...(x.lesson===LESSON?progress:saved)};}));const data={records,format:'courtiq-learning-progress-v1',lessonId:LESSON.id,lessonVersion:LESSON.version,caseId:LESSON.caseId,exportedAt:new Date().toISOString(),...progress};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='CourtIQ_Ice_Learning_Notes.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('已匯出學習紀錄，不含影片或個人帳號。');}

function selectLesson(courseId,caseId){const nextTime=courseId===LESSON.id?state.t:0,changedCourse=courseId!==LESSON.id;pause();activateLesson(courseId,caseId);if(changedCourse)state.role=LESSON.defaultRole||'C';try{progress=readProgress(localStorage.getItem(storageKey()));storageWorks=true;}catch{progress=readProgress(null);storageWorks=false;}state.t=clamp(LESSON.previewTime??nextTime,0,LESSON.duration);state.mode='watch';state.guess=null;state.revealed=false;state.future=false;lastPhase=-1;$('roleNote').value=progress.notes[state.role]||'';renderLesson();render();$('saveStatus').textContent=storageWorks?'本情境的紀錄保存在此瀏覽器':'此瀏覽器無法保存；請匯出紀錄備份';}
function renderLibrary(){
 $('categoryFilters').replaceChildren(...['全部',...new Set(COURSES.map(c=>c.category))].map(category=>{const b=document.createElement('button');b.textContent=category;b.setAttribute('aria-pressed',String(category===categoryFilter));b.onclick=()=>{categoryFilter=category;coursePage=0;renderLibrary();};return b;}));
 const result=getCoursePage(COURSES,{category:categoryFilter,query:courseQuery,page:coursePage,pageSize:COURSE_PAGE_SIZE});coursePage=result.index;$('searchCount').textContent=`找到 ${result.count} 堂`;$('noCourses').hidden=result.count!==0;$('coursePagination').hidden=result.pages<=1;$('previousCoursePage').disabled=coursePage===0;$('nextCoursePage').disabled=coursePage>=result.pages-1;$('coursePageLabel').textContent=`${coursePage+1} / ${result.pages} 頁`;$('directoryCount').textContent=`${COURSES.length} 堂課 · ${scenarios.length} 個情境`;$('currentCourseName').textContent=`目前：${LESSON.number} ${COURSES.find(c=>c.id===LESSON.id).title}`;$('coursePicker').replaceChildren(...result.items.map(c=>{const b=document.createElement('button');b.type='button';b.className='course-card';b.setAttribute('aria-pressed',String(c.id===LESSON.id));const number=document.createElement('span'),title=document.createElement('strong'),detail=document.createElement('small');number.textContent=c.number;title.textContent=c.title;detail.textContent=`${c.cases.length} 個情境 · ${c.focus}`;b.append(number,title,detail);b.onclick=()=>{selectLesson(c.id,c.cases[0].id);$('courseDirectory').open=false;$('courseDirectory').querySelector('summary').focus({preventScroll:true});};return b;}));updateBankProgress();
}
$('courseSearch').addEventListener('input',e=>{courseQuery=e.target.value;coursePage=0;renderLibrary();});$('previousCoursePage').onclick=()=>{coursePage--;renderLibrary();};$('nextCoursePage').onclick=()=>{coursePage++;renderLibrary();};
function nextScenario(){const index=scenarios.findIndex(x=>x.scenario.lesson===LESSON),next=scenarios[(index+1)%scenarios.length];categoryFilter='全部';selectLesson(next.course.id,next.scenario.id);toast('已切換下一個情境；先觀察，再試著預判。');}
function randomPractice(){const current=LESSON;randomBag=randomBag.filter(x=>x.scenario.lesson!==current);if(!randomBag.length){randomBag=scenarios.filter(x=>x.scenario.lesson!==current);for(let i=randomBag.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[randomBag[i],randomBag[j]]=[randomBag[j],randomBag[i]];}}const next=randomBag.pop();categoryFilter='全部';selectLesson(next.course.id,next.scenario.id);state.role=LESSON.defaultRole||'C';$('roleNote').value=progress.notes[state.role]||'';beginPractice();toast('先觀察球、人與方向，再選下一步。');}
$('nextScenario').onclick=nextScenario;$('nextPractice').onclick=()=>{nextScenario();document.querySelector('.lesson-heading').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});};$('randomPractice').onclick=randomPractice;

function renderLesson(){
 const course=COURSES.find(c=>c.id===LESSON.id);$('courseTotal').textContent=COURSES.length+' LESSONS';
 const index=scenarios.findIndex(x=>x.scenario.lesson===LESSON);$('scenarioLabel').textContent=`情境 ${String(index+1).padStart(2,'0')} / ${scenarios.length} · ${course.cases.find(c=>c.id===LESSON.caseId).label}`;
 const defend=LESSON.direction==='defend';document.querySelector('.zoom-direction').textContent=defend?'對手向左進攻 ←':'己方向右進攻 →';$('attackText').textContent=defend?'對手進攻':'己方進攻';$('attackArrow').setAttribute('d',defend?'M925 27 H863 l9 -5 M863 27 l9 5':'M863 27 H925 l-9 -5 M925 27 l-9 5');
 $('goalies').replaceChildren(...[[130,'#277b76'],[870,'#667774']].map(([x,color])=>{const g=el('g',{transform:`translate(${x} 300)`,'aria-label':x===130?'己方守門員固定示意':'對方守門員固定示意'});g.append(el('circle',{r:15,fill:color,opacity:.55,stroke:'#fff','stroke-width':2}),el('text',{class:'token-label',style:'font-size:11px'},'G'));return g;}));
 renderLibrary();
 $('caseHelp').textContent=LESSON.learningFocus||LESSON.practiceIntro;$('casePanel').hidden=course.cases.length<2;$('casePicker').replaceChildren(...course.cases.map(x=>{const b=document.createElement('button');b.textContent=x.label;b.setAttribute('aria-pressed',String(x.id===LESSON.caseId));b.onclick=()=>selectLesson(course.id,x.id);return b;}));
 document.querySelector('.lesson-index').textContent=LESSON.number;document.querySelector('.lesson-heading .eyebrow').textContent=LESSON.eyebrow;document.querySelector('.lesson-heading h2').textContent=LESSON.title;document.querySelector('.duration').textContent=LESSON.duration+' 秒示範 · 可重播';$('timeline').max=LESSON.duration;$('totalTime').textContent=LESSON.duration.toFixed(1);$('practiceHint').textContent=`在 ${LESSON.checkpoint.toFixed(1)} 秒停住，選你接下來的位置，再看示範。`;
 const ticks=LESSON.ticks||(LESSON.number==='02'?['控制球','給邊線','讀防守','向前推進']:['爭球準備','球回後衛','回繞接應','準備進區']);document.querySelectorAll('.timeline-ticks span').forEach((n,i)=>n.textContent=ticks[i]);document.querySelectorAll('.role-switch [data-role]').forEach(b=>b.querySelector('small').textContent=LESSON.roles[b.dataset.role].job);$('neutralView').textContent=LESSON.number!=='01'?'位置放大':'中區放大';$('rinkTitle').textContent=LESSON.title;$('lessonContext').textContent=LESSON.context;if(LESSON.source.url){$('lessonSource').href=LESSON.source.url;$('lessonSource').textContent=LESSON.source.label+' ↗';}else{$('lessonSource').removeAttribute('href');$('lessonSource').textContent=LESSON.source.label;}document.querySelectorAll('.takeaway-grid article').forEach((n,i)=>{n.querySelector('h3').textContent=LESSON.takeaways[i].title;n.querySelector('p').textContent=LESSON.takeaways[i].body;});
}

for(const b of document.querySelectorAll('.role-switch [data-role]'))b.addEventListener('click',()=>setRole(b.dataset.role));$('players').addEventListener('click',e=>{const n=e.target.closest('[data-role]');if(n)setRole(n.dataset.role);});$('players').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){const n=e.target.closest('[data-role]');if(n){e.preventDefault();e.stopPropagation();setRole(n.dataset.role);}}});
$('rink').addEventListener('click',e=>{if(e.target.closest('[data-role]'))return;if(state.mode!=='predict')return;const p=$('rink').createSVGPoint();p.x=e.clientX;p.y=e.clientY;const q=p.matrixTransform($('rink').getScreenCTM().inverse());setGuess(q.x,q.y);});
$('rink').addEventListener('keydown',e=>{if(state.mode!=='predict')return;const directions={ArrowLeft:[-15,0],ArrowRight:[15,0],ArrowUp:[0,-15],ArrowDown:[0,15]};if(directions[e.key]){e.preventDefault();const d=directions[e.key];keyCursor={x:clamp(keyCursor.x+d[0],40,960),y:clamp(keyCursor.y+d[1],50,550)};setGuess(keyCursor.x,keyCursor.y);}else if(e.key==='Enter'&&e.target===$('rink')){e.preventDefault();setGuess(keyCursor.x,keyCursor.y);}});
$('play').onclick=()=>state.playing?(pause(),renderCopy()):play();$('restart').onclick=()=>{setTime(0);state.guess=null;state.future=false;render();};$('stepBack').onclick=()=>{const starts=LESSON.phases.map(p=>p.start).filter(t=>t<state.t-.05);setTime(starts.at(-1)||0);};$('stepNext').onclick=()=>{setTime(LESSON.phases.find(p=>p.start>state.t+.05)?.start??LESSON.duration);};$('timeline').oninput=e=>setTime(Number(e.target.value));$('speed').onchange=e=>{state.speed=Number(e.target.value);};$('fullView').onclick=()=>{state.zoom=false;renderBoard();};$('neutralView').onclick=()=>{state.zoom=true;renderBoard();};$('showTrails').onchange=e=>{state.trails=e.target.checked;renderBoard();};$('showOpponents').onchange=e=>{state.opponents=e.target.checked;renderBoard();};$('showSupport').onchange=e=>{state.support=e.target.checked;renderBoard();};
$('futureToggle').onclick=()=>{if(state.mode==='predict'){toast('這次先保留預判，選點後再揭曉。');return;}state.future=!state.future;$('futureToggle').setAttribute('aria-pressed',String(state.future));$('futureToggle').textContent=state.future?'隱藏下一段路線':'顯示下一段路線';renderBoard();};$('practice').onclick=beginPractice;$('reveal').onclick=()=>{if(!state.guess)return;state.mode='watch';state.revealed=true;state.future=true;state.t=LESSON.predictionTime;progress.predictions[state.role]={...state.guess};persist();$('futureToggle').setAttribute('aria-pressed','true');$('futureToggle').textContent='隱藏下一段路線';render();};$('markViewed').onclick=()=>{const was=progress.viewed.includes(state.role);if(was)progress.viewed=progress.viewed.filter(r=>r!==state.role);else progress.viewed.push(state.role);persist();updateProgress();toast((was?'已取消標記 ':'已標記看過 ')+state.role+' '+LESSON.roles[state.role].name);};$('roleNote').addEventListener('input',()=>{progress.notes[state.role]=$('roleNote').value;persist();});$('exportProgress').onclick=exportProgress;document.addEventListener('visibilitychange',()=>{if(document.hidden){pause();renderCopy();}});
renderLesson();makeTokens();experiences=mountExperiences({selectSource:(id,caseId)=>{if(!COURSES.some(c=>c.id===id&&c.cases.some(s=>s.id===caseId)))throw new Error('來源課程已不存在，無法載入此演練');selectLesson(id,caseId);},getMeta:()=>({lesson:LESSON,role:state.role,t:state.t,caseLabel:COURSES.find(c=>c.id===LESSON.id).cases.find(c=>c.id===LESSON.caseId).label}),getFrame:(time=state.t)=>({t:time,lessonId:LESSON.id,caseId:LESSON.caseId,direction:LESSON.direction,own:Object.fromEntries(ROLE_IDS.map(id=>[id,position(id,time)])),opponents:Object.fromEntries(Object.entries(LESSON.opponents).map(([id,points])=>[id,sample(points,time)])),puck:puck(time)})});$('roleNote').value=progress.notes.C||'';render();if(!storageWorks)$('saveStatus').textContent='此瀏覽器無法保存；請匯出紀錄備份';
